普通的trie当然做不了啦，毕竟输入这么大。

正确的姿势应该是压缩字典树吧，因为N的规模比较小，所以压缩字典树的结点数量也会相对较小。

实际上不需要查找——我是在递归建树时存一下有没有对树进行修改，有修改过就把答案+1(s)，没有的话就意味着找到了完全相同的路径，也就是说这个串已经出现过了。

当然，速度还是要比hash慢不少的。

不知为何读入写错了= =wa了好几次。

附代码

#include<iostream>
#include<cstring>
using namespace std;
struct Node{
    int st,ed,cnt;
    Node *ch[64];
    char sus[64];
};
int ans=0;
char sus[20000000],c[20000],re;
Node *t=new(Node),*tnode;
int n,cmq,len,size,tmp;
void clear(Node *p){
    p->st=p->ed=size;
    p->cnt=0;
}
int same(Node *p,int st){
    int i;
    for(i=0;p->st+i < p->ed&&st+i<len&&c[st+i]==sus[ p->st +i];i++);
    return i;
}
void diliver(Node * &p,int len){
    Node *t=new(Node);
    t->st=p->st;
    t->ed=t->st+len;
    t->cnt=1;
    t->sus[0]=sus[t->ed];
    t->ch[0]=p;
    p->st=t->ed;
    p=t;
}
int find(Node *p,char ch){
    for(int i=0;i< p->cnt;i++)
        if(p->sus[i]==ch)
            return i;
    return -1;
}
void insert(Node *&p,int st,int flag){
    int ll;
    ll=same(p,st);
    if(ll==p->ed - p->st){
        st=st+ll;
    }
    else{
        diliver(p,ll);
        flag=1;
        st=st+ll;
    }
    if(st==len){
        if(flag) ans++;
        return;
    }
    else{
        tmp=find(p,c[st]);
        if(tmp!=-1) insert(p->ch[tmp],st,flag);
        else{
            tnode=new(Node);
            p->ch[p->cnt]=tnode;
            p->sus[p->cnt]=c[st];
            p->cnt++;
            clear(tnode);
            for(int i=st;i<len;i++)
                sus[tnode->ed++]=c[i];
            size=tnode->ed;
            flag=1;
            if(flag) ans++;
            return;
        }
    }
}
int main(){
    clear(t);
    cin>>n;
    for(int i=0;i<n;i++){
        cin>>c;
        len=strlen(c);
        insert(t,0,0);
    }
    cout<<ans<<"\n";
    return 0;
}
